/* qw-themes-0.js: Quiet Words themes. Lines adapted from Open English WordNet (CC BY 4.0) or written by hand, puzzles 1 to 41. Made by tools/word-games. Do not edit by hand. */
(window.TOL_PUZZLES = window.TOL_PUZZLES || {})["qw-themes-0"] = [{"name":"Calm","words":[["CALM","Calm isn’t the absence of feelings. It’s a little room around them."],["BREATHE","Your breath is always there to come back to."],["REST","Rest is part of the work, not a break from it."],["SOFT","You’re allowed to be soft with yourself today."],["STILL","A still moment is enough. It doesn’t have to be long."],["EASE","Ease in. There’s no rush here."],["QUIET","Quiet is a kind of kindness to your mind."],["SLOW","Slow is still moving."],["HUSH","Hush is a gift you can give a busy mind."],["PEACE","Peace can be as small as one slow breath."],["SERENE","Serene is a lake with no wind. You can visit it any time."],["SETTLE","Let your shoulders settle. They've worked hard today."],["GENTLE","Be gentle with the pace of this moment."]]},{"name":"Kindness","words":[["KIND","Kindness counts most when it’s small and ordinary."],["GENTLE","Gentle is strong. It just doesn’t shout."],["CARE","Caring for yourself is how you keep caring for others."],["SMILE","Smile at someone today. It travels further than you think."],["THANKS","Say one specific thank-you before the day ends."],["HUG","A slow hug helps two people settle."],["HELP","Asking for help is a kindness to the person you ask."],["WARM","Warmth is remembered long after words are forgotten."],["SHARE","Sharing makes the good things go further."],["LISTEN","Listening closely is one of the kindest gifts."],["COMFORT","A little comfort can change someone's whole day."],["PATIENT","Patience is kindness that takes its time."],["FRIEND","Be the friend you'd love to have."]]},{"name":"Night Garden","words":[["MOON","The moon is never really gone. Neither is calm."],["STARS","Even on cloudy nights, the stars are still there."],["FIREFLY","Small lights matter. Be one for someone today."],["BLOOM","You bloom in your own season."],["POND","Let your thoughts settle, like water going still."],["LILY","Float for a while. You don’t have to swim hard."],["GLOW","The glow comes back after rest."],["BREEZE","Let a worry pass by like a breeze."],["OWL","The owl keeps watch while the garden rests."],["MOTH","Moths find the light. So can you."],["LANTERN","A small lantern is enough to find the path."],["DEW","Dew arrives quietly, and so does rest."],["HUSH","The garden at night knows how to hush."]]},{"name":"Connection","words":[["TOGETHER","Most of closeness is ordinary moments, shared."],["LISTEN","Listening is one of the kindest things you can do."],["TRUST","Trust is built in small, kept promises."],["SHARE","Share one good thing from your day."],["LAUGH","Laughing together is a small repair."],["FRIEND","Send a friend a “thinking of you”."],["HOME","Home is often a person, not a place."],["LOVE","Love shows up in how we answer the little moments."],["HUG","A hug says what words sometimes can't."],["CHAT","A short chat can make a long day lighter."],["VISIT","A visit, even a quick one, is a gift."],["BOND","Bonds grow stronger with small, kind moments."],["WELCOME","Make someone feel welcome today."]]},{"name":"Gratitude","words":[["GRATEFUL","Name three things that went okay today. Small counts."],["GIFT","Today is a small gift, even the plain parts."],["JOY","Joy is often tiny. Look for it at eye level."],["LIGHT","Let a little light in, even through a crack."],["HOPE","Hope is a quiet thing. It still counts."],["GROW","You’re growing, even when it doesn’t feel like it."],["ENOUGH","You are doing enough."],["SUNRISE","Tomorrow starts fresh."],["THANKS","Say thanks for one small thing."],["BLESSING","Count one quiet blessing before you sleep."],["SMILE","A smile is a thank-you without words."],["SHARE","Gratitude grows when it's shared."],["WARMTH","Notice the warmth around you today."]]},{"name":"Paws","words":[["PAWS","For the small companions who love us without words."],["WAG","Be as glad to see someone as a dog is."],["PUPPY","Play is good for grown-ups too."],["TREAT","Give yourself a small treat today."],["CUDDLE","Comfort counts. Let yourself be comforted."],["WALK","A short walk can lift a whole day."],["LOYAL","Loyalty is love that keeps showing up."],["FETCH","Chase something just for the fun of it."],["BARK","A happy bark means \"you're home!\""],["NUZZLE","A nuzzle is a small way of saying \"I love you\"."],["COLLAR","A collar with a name says \"you belong here\"."],["BALL","Throw the ball once more. Play is good for you both."]]},{"name":"Morning","words":[["DAWN","Every dawn is a quiet invitation to begin again."],["COFFEE","Hold your warm mug for a moment before the first sip."],["STRETCH","A slow stretch tells your body, “Good morning, I’m here.”"],["BIRDSONG","Listen for one bird this morning. It’s singing anyway."],["TOAST","Simple breakfasts can be the loveliest ones."],["FRESH","Today hasn’t been written yet. It’s fresh for you."],["SUNBEAM","Find a sunbeam and stand in it for a breath or two."],["WAKE","Wake gently. The day can wait a minute."],["SUNRISE","Every sunrise is a fresh start."],["KETTLE","Put the kettle on. The day can wait a moment."],["YAWN","A slow yawn is a gentle way to begin."],["DEW","Morning dew: the world washed fresh."],["HELLO","Say a warm hello to the day."]]},{"name":"Evening","words":[["DUSK","Dusk is the day softening its edges. You can too."],["SUNSET","Pause for the sunset, even through a window."],["UNWIND","Let the day unwind from your shoulders, one breath at a time."],["SLIPPERS","Slippers on means the busy part is over."],["CANDLE","A small flame can make a whole room feel calmer."],["SUPPER","A simple supper, eaten slowly, is a lovely thing."],["TWILIGHT","Twilight is a gentle in-between. Let yourself drift."],["SETTLE","Settle in. You did what you could today."],["LAMP","Switch on a soft lamp and let the day go."],["BATH","A warm bath can wash the day away."],["STARS","The first stars mean it's time to rest."],["QUIET","Let the evening grow quiet around you."],["MOON","The moon comes out to keep you company."]]},{"name":"Seaside","words":[["SHELL","Pick up a shell and notice its tiny, patient patterns."],["WAVES","Waves come and go. So do feelings."],["SANDY","Sandy toes are a sign of a day well spent."],["PEBBLE","Smooth pebbles were shaped slowly. So are we."],["HARBOUR","Everyone deserves a safe harbour. You can be one too."],["SEAGULL","Let the seagulls be noisy so you don’t have to be."],["TIDE","The tide always turns. Things change, gently."],["BREEZY","Let a salty breeze blow the cobwebs away."],["SAND","Feel the sand between your toes."],["SHORE","The shore is where busy thoughts can wash away."],["SPLASH","A little splash wakes up the whole day."],["BUCKET","A bucket and spade: the simplest kind of fun."],["SALT","Salt air is good for the soul."]]},{"name":"Forest","words":[["TREES","Trees grow slowly and stand tall. There’s no hurry."],["MOSS","Moss is proof that soft things can thrive anywhere."],["FERN","Ferns unfurl one curl at a time."],["ACORN","Every great oak started as a small acorn."],["PINE","Breathe in the smell of pine and let your shoulders drop."],["CANOPY","Look up at the canopy. There’s a whole world above."],["OAK","Be steady like an oak, and still sway in the wind."],["BIRCH","Birch trees shed their bark and carry on. Renewal is natural."],["BARK","Touch the bark of a tree and take a slow breath."],["LEAF","Every leaf turns toward the light."],["SQUIRREL","Squirrels save a little for later. So can you."],["OWL","The owl knows the value of a quiet night."],["PATH","The path is kinder when you walk it slowly."]]},{"name":"Rainy Day","words":[["PUDDLE","Jump in a puddle. Nobody’s too old for that."],["UMBRELLA","Let someone share your umbrella. Or share theirs."],["DRIZZLE","A soft drizzle is a lovely excuse to stay in."],["WELLIES","Pull on your wellies and go and splash about."],["RAINBOW","Rainbows need a little rain first."],["CLOUDS","Clouds drift on. So will this grey patch."],["COSY","Rainy days are made for getting cosy."],["WINDOW","Watch raindrops race down the window. Pick a favourite."],["DRIP","Listen to the drip. It's a kind of music."],["BOOTS","Pull on your boots and meet the rain."],["SPLASH","Splash in one puddle, just because."],["BLANKET","Rain on the window, a blanket on your knees."],["TEA","Rainy days were made for a pot of tea."]]},{"name":"Snow Day","words":[["SNOWMAN","Build a snowman and give them a kind smile."],["MITTENS","Warm hands, warm heart. Pop your mittens on."],["SLEDGE","Whee! A little fun is good for everyone."],["SCARF","Wrap up snugly. You deserve to be warm."],["COCOA","A mug of cocoa is a hug you can hold."],["FLAKES","No two snowflakes are alike. Nor are you."],["FROSTY","Frosty mornings make the world sparkle."],["IGLOO","Even snow can make a shelter. Warmth is found in odd places."],["SNOWBALL","A gentle snowball: play is allowed."],["BOOTS","Boots on. Every snowy step crunches."],["SLED","A slow sled ride down a little hill."],["HAT","A woolly hat keeps the cold at bay."]]},{"name":"Spring","words":[["BLOSSOM","Blossom takes its time and then it’s glorious."],["TULIP","Tulips keep growing in the vase. Growth doesn’t stop."],["LAMBS","Watch lambs leap for no reason at all. Joy needs no excuse."],["DAFFODIL","Daffodils are spring saying, “Hello, I’m back.”"],["BUDS","Tiny buds are a promise of what’s coming."],["NEST","Make your space a little nest. Comfort matters."],["SPROUT","New beginnings often start very small."],["MEADOW","Imagine a meadow full of flowers, swaying gently."],["BUD","Every bud holds a flower waiting its turn."],["RAIN","Spring rain helps everything grow, including you."],["ROBIN","The robin sings as if the whole day is new."],["GREEN","Notice all the shades of new green."],["BLOOM","You'll bloom in your own time."]]},{"name":"Summer","words":[["SUNSHINE","Let a little sunshine warm your face today."],["BEACH","Picture your favourite beach and breathe with the waves."],["PADDLE","Paddle your feet in cool water. Simple and lovely."],["LEMONADE","Sweet, sharp and fresh, just like a summer afternoon."],["SANDALS","Light feet, light heart."],["HAMMOCK","Sway in a hammock, real or imagined. Let yourself rest."],["ICECREAM","Pick your favourite flavour and savour every bite."],["DAISY","Make a daisy chain, or simply notice the daisies."],["SWIM","A cool swim on a warm day."],["PICNIC","A picnic on the grass is a little holiday."],["SUNHAT","Wear a sunhat and take things slowly."],["BREEZE","Wait for the breeze. It always comes."]]},{"name":"Autumn","words":[["LEAVES","Trees let their leaves go and they’re still beautiful."],["CONKER","Shiny conkers are little treasures. Pick one up."],["AMBER","Autumn light turns everything amber and gold."],["HARVEST","Take a moment to gather up what went well this year."],["JUMPER","Your favourite jumper is a kind of comfort."],["APPLES","Crisp apples, warm crumble. Autumn is generous."],["PUMPKIN","Pumpkin soup and a blanket make a fine evening."],["CRUNCH","Find a pile of leaves and crunch through it."],["ACORN","Big oaks start as little acorns."],["SCARF","Wrap up warm and go for a walk."],["GOLDEN","Autumn light makes everything golden."],["MIST","Morning mist lifts slowly. Let your worries lift too."],["CHESTNUT","Roasted chestnuts warm hands and hearts."]]},{"name":"Winter","words":[["FIRESIDE","Sit by something warm and let the chill melt away."],["BLANKET","Wrap yourself in a blanket. You’re allowed to be comfy."],["SNUG","Snug is a lovely word and an even lovelier feeling."],["FROST","Frost draws patterns on the glass. Stop and look."],["SOUP","A bowl of soup is warmth from the inside out."],["WOOLLY","Pull on something woolly and feel cosy."],["HOLLY","Holly stays green all winter. Hope can too."],["GLOVES","Keep your hands warm and your heart warmer."],["SNOW","Snow makes the whole world hush."],["MITTENS","Warm hands, warm heart."],["COCOA","A mug of cocoa is winter's hug."],["CANDLE","A candle in the window lights the long evening."],["QUILT","Curl up under a quilt and rest."]]},{"name":"Tea Time","words":[["TEAPOT","A pot of tea is an invitation to slow down."],["KETTLE","While the kettle boils, take three slow breaths."],["BISCUIT","Have a biscuit. Dunking is encouraged."],["SCONE","Jam first or cream first? Either way is lovely."],["CUPPA","Put the kettle on for someone. It says a lot."],["SAUCER","Small, thoughtful touches make ordinary moments special."],["BREW","Let your tea brew. Some good things take a few minutes."],["CRUMPET","Warm crumpets and butter: a simple joy."],["MILK","A splash of milk, just how you like it."],["SUGAR","One lump or two? Treat yourself."],["CAKE","Tea tastes better with a slice of cake and company."],["STEAM","Watch the steam rise and slow down with it."],["CUP","A warm cup, held in both hands."]]},{"name":"Baking","words":[["FLOUR","A little mess in the kitchen can mean a lot of love."],["WHISK","Whisk away a worry while you mix."],["DOUGH","Kneading dough is a lovely way to let off steam."],["OVEN","The smell of baking makes any house feel like home."],["SPRINKLE","Add sprinkles. Life’s better with a little extra."],["MUFFIN","Share a muffin with a neighbour. Crumbs of kindness."],["ICING","Imperfect icing still tastes wonderful."],["RECIPE","Your own way of doing things is a recipe worth keeping."],["BUTTER","Softened butter makes everything better."],["SUGAR","A little sweetness goes a long way."],["EGGS","Crack the eggs and start something new."],["BOWL","Mix it all in one big bowl."],["CAKE","A cake shared is joy doubled."]]},{"name":"Garden","words":[["SEEDS","Plant a seed of kindness today and see what grows."],["ROSES","Stop and smell the roses. Really, it helps."],["TROWEL","A little digging in the soil is good for the soul."],["POTTING","Potting about with no plan is time well spent."],["LAVENDER","Brush past some lavender and breathe in slowly."],["SHED","Everyone needs a quiet corner of their own."],["HEDGE","Hedges shelter small birds. Kindness shelters people."],["BLOOMS","Some blooms come early and some come late. All are lovely."],["WORM","Worms quietly make the soil rich."],["WATER","Water the plants, and drink some water too."],["BUD","A bud is a promise of colour."],["BENCH","Sit on the bench and simply look."]]},{"name":"Birds","words":[["ROBIN","A robin is often a friendly little visitor. Say hello."],["WREN","The tiny wren has one of the loudest songs. Small is mighty."],["SPARROW","Ordinary sparrows are quietly wonderful. So are you."],["FEATHER","Be as light as a feather for a moment."],["NESTLE","Nestle into somewhere comfortable and rest a while."],["SONG","Hum a little song. Nobody needs to hear it but you."],["OWL","Owls see well in the dark. Your way will become clear."],["SWALLOW","Swallows always find their way home."],["BLACKBIRD","The blackbird sings from the rooftop at dusk."],["THRUSH","The thrush sings each phrase twice, to be sure."],["FINCH","Finches chatter together in the hedge."],["NEST","Every nest is built one twig at a time."],["WING","Stretch your wings a little today."]]},{"name":"Butterflies","words":[["WINGS","Change can give you wings."],["FLUTTER","Let your thoughts flutter by without chasing them."],["NECTAR","Seek out the sweet things in your day."],["PETALS","Rest on the soft things for a while."],["CLOVER","Look closely at the clover. Little luck is everywhere."],["FLOAT","Float along today. There’s no need to rush."],["BRIGHT","Your bright colours are welcome here."],["GARDEN","Plant flowers for butterflies and they’ll come to visit."],["CATERPILLAR","Every butterfly was once a caterpillar."],["MEADOW","A meadow is a butterfly's favourite place."],["COLOUR","Wings full of colour, and you are too."],["BLOSSOM","Blossom and butterflies arrive together."],["SUMMER","Summer days are made for fluttering."]]},{"name":"Ocean Life","words":[["DOLPHIN","Dolphins play for the joy of it. Play a little today."],["WHALE","Whales sing across whole oceans. Your voice carries too."],["OTTER","Otters hold hands while they sleep so they don’t drift apart."],["SEAHORSE","Seahorses move slowly and gracefully. Slow is fine."],["CORAL","Coral is built by many tiny friends working together."],["TURTLE","Turtles carry their home with them. Comfort can travel."],["STARFISH","Starfish can regrow. You can grow back stronger too."],["SEAL","Bask like a seal on a sunny rock. Rest is allowed."],["OCTOPUS","The clever octopus hugs with eight arms."],["CRAB","Crabs carry their homes wherever they go."],["JELLYFISH","The jellyfish simply drifts. Drifting is fine."],["PUFFIN","Puffins return to the same cliffs every year."],["REEF","A reef is a whole town under the sea."]]},{"name":"Stars and Sky","words":[["COMET","Comets come round again. Good things return."],["GALAXY","You’re made of the same stuff as the stars."],["ORBIT","Notice who orbits your life with kindness."],["PLANET","This little planet is lucky to have you on it."],["NEBULA","Stars are born in clouds. New beginnings can be hazy."],["MOONLIT","Take a moonlit moment to simply look up."],["WISH","Make a wish. Hoping is a lovely thing to do."],["HORIZON","There’s always more sky beyond the horizon."],["MOON","The moon shines with borrowed light. We all help each other shine."],["STAR","Wish on the first star you see."],["TWINKLE","Twinkle, twinkle: some things never grow old."],["SUNSET","A sunset is the sky saying \"well done\"."],["TELESCOPE","Look up. There's always more to wonder at."]]},{"name":"Music","words":[["MELODY","Find a melody that makes you feel at home."],["HUM","Humming is a small, soothing song for yourself."],["RHYTHM","Find your own rhythm. It doesn’t need to match anyone’s."],["PIANO","Soft piano music can make a room feel calmer."],["CHORUS","Sing the chorus loudly, even if it’s only in the car."],["GUITAR","A few strummed chords can gently change a mood."],["LULLABY","Hum yourself a lullaby tonight."],["HARMONY","Different notes make harmony. Differences make life richer."],["SONG","Hum a song that makes you happy."],["DRUM","Tap a gentle beat on the table."],["FLUTE","A flute sounds like a breeze with a tune."],["VIOLIN","A violin can sing without words."],["CHOIR","Voices together sound bigger than alone."]]},{"name":"Colours","words":[["VIOLET","Violets grow in quiet places and still bring colour."],["SAGE","Soft sage green is the colour of calm."],["INDIGO","Indigo evenings are made for winding down."],["TEAL","Teal is the colour of a calm sea on a clear day."],["PEACH","Peachy skies at sunset are worth a pause."],["LILAC","Lilac is gentle and sweet, like a kind word."],["GOLDEN","Look for golden moments. They’re often small."],["ROSY","Rosy cheeks, rosy skies. Colour is everywhere today."],["BLUE","Blue skies are always there above the clouds."],["GREEN","Green is the colour of growing things."],["YELLOW","Yellow is sunshine you can hold."],["CORAL","Coral is warm like a summer evening."],["CREAM","Soft cream, like a cosy blanket."]]},{"name":"Home","words":[["DOORSTEP","Crossing your own doorstep can feel like a sigh of relief."],["KITCHEN","The kitchen is often where the best chats happen."],["SOFA","Sink into the sofa. You’ve earned a sit down."],["WELCOME","Make someone feel welcome today."],["CUSHION","Plump a cushion and get comfy."],["SHELF","Put something that makes you smile on a shelf you see often."],["NOOK","Find a little nook that feels like yours."],["PORCH","Leave the porch light on for someone."],["DOOR","The door is always open to those you love."],["KETTLE","Home is the sound of the kettle going on."],["GARDEN","A little garden makes a house a home."],["WINDOW","Look out of the window and let your eyes rest."],["HEARTH","The hearth is the warm heart of a home."]]},{"name":"Cosy","words":[["SNUGGLE","Snuggle up. Comfort is good for you."],["FLEECE","Soft fleece and warm tea: a small, cosy kindness."],["SOCKS","Fluffy socks make everything a little better."],["DUVET","A duvet day now and then is perfectly fine."],["PILLOW","Plump your pillow and rest your head."],["COCOON","Wrap yourself up like a cocoon. Change happens in quiet."],["KNITTED","Something knitted holds the warmth of the hands that made it."],["FIRELIT","Firelit evenings are made for slow conversations."],["BLANKET","Wrap yourself up. You deserve comfort."],["CANDLE","A candle's glow makes any room cosy."],["COCOA","Warm cocoa for cold hands."],["SLIPPERS","Slippers on. You're home now."],["QUILT","A patchwork quilt holds many stories."]]},{"name":"Friendship","words":[["BUDDY","A buddy makes the ordinary feel like an adventure."],["PAL","Check in on a pal. A small hello goes a long way."],["LOYALTY","Loyalty is showing up again and again."],["CHAT","A long chat with a friend can make the world feel lighter."],["GIGGLE","Share a giggle with someone today."],["MATES","Good mates remember the little things."],["KINDRED","A kindred spirit is a lovely thing to find."],["SUPPORT","You don’t have to fix things. Just being there is support."],["FRIEND","A friend makes the good times brighter and the hard times lighter."],["LAUGH","Laughing together is a kind of glue."],["SHARE","Share a snack, share a story."],["HUG","A friend's hug is a safe place."],["TRUST","Trust grows slowly, like a tree."]]},{"name":"Family","words":[["SIBLING","Siblings share stories nobody else knows."],["GRANNY","Some of the kindest wisdom comes from grannies."],["COUSIN","Send a cousin a friendly hello."],["AUNTIE","Aunties often have the best stories and the warmest hugs."],["UNCLE","Share a silly joke, the kind an uncle might tell."],["ROOTS","Your roots help you grow, wherever you are."],["HUDDLE","A family huddle can be any group that loves you."],["STORIES","Ask someone to tell you a story from when they were young."],["HOME","Family is where you can simply be yourself."],["HUG","A family hug has room for everyone."],["MEAL","Sharing a meal is sharing time."],["PHOTO","Old photos keep the stories alive."],["GRANDPA","Grandpa's stories are treasures."]]},{"name":"Self-Kindness","words":[["WORTHY","You are worthy of kindness, especially your own."],["FORGIVE","Forgive yourself for the little things. You’re learning."],["ACCEPT","Accept where you are today. It’s a fine place to start."],["TENDER","Be tender with yourself, as you would with a friend."],["BOUNDARY","A kind boundary protects your energy."],["PAUSE","Pause before being hard on yourself. Try a gentler word."],["NOURISH","Nourish yourself with something you enjoy today."],["VALUED","You are valued just as you are."],["REST","Rest is not a reward. It's a need."],["GENTLE","Speak to yourself as you would to a friend."],["ENOUGH","You are enough, just as you are."],["BREATHE","Breathe in kindness, breathe out worry."],["CARE","Take care of the one who takes care of everything."]]},{"name":"Hope","words":[["DAYBREAK","Daybreak always comes. Light finds its way."],["SEEDLING","Seedlings push through soil. Small steps count."],["BELIEVE","Believe that good things can still happen."],["BRIGHTER","Brighter days often arrive quietly."],["WISH","Hold a wish in your heart and let it be gentle."],["ONWARD","Onward, one small step at a time."],["RENEW","Every day is a chance to renew."],["LANTERN","Hope is a lantern. It doesn’t have to be big to light the way."],["DAWN","Dawn always comes, even after the longest night."],["SPRING","Spring follows winter. It always has."],["RAINBOW","After rain, look for the rainbow."],["DREAM","Keep a small dream in your pocket."],["LIGHT","A little light is enough to take the next step."]]},{"name":"Courage","words":[["BRAVE","Being brave can be quiet too."],["BOLD","Try one bold, kind thing today."],["STEADY","Steady is its own kind of strong."],["TRY","Trying is brave. The outcome is a bonus."],["HEART","Courage comes from the heart. Yours is doing well."],["VOICE","Your voice matters. Let it be heard, gently."],["ANYWAY","Feeling nervous and doing it anyway is real courage."],["STRIDE","Take things in your stride, one step at a time."],["LION","Courage can be quiet, like a lion at rest."],["SPEAK","Your voice matters. Use it kindly."],["STAND","Stand tall. You've come so far."],["LEAP","Sometimes a small leap is all it takes."],["HERO","Everyday heroes do small brave things."]]},{"name":"Patience","words":[["WAIT","Waiting can be a quiet gift of time."],["GRADUAL","Gradual change is still change."],["SEASON","Everything has its season, including you."],["RIPEN","Good things ripen in their own time."],["TIMING","Your timing is your own. There’s no race."],["TORTOISE","The tortoise got there in the end. Slow and steady works."],["LINGER","Linger over something lovely today."],["MOMENT","Give this moment your full attention."],["SEED","A seed takes its time. So can you."],["SLOW","Slow and steady is still moving forward."],["CALM","Calm waiting is a quiet strength."],["GROW","Things grow at their own pace."],["STEADY","Steady steps get there in the end."]]},{"name":"Joy","words":[["DELIGHT","Let yourself delight in something small."],["SPARKLE","You have a sparkle that’s all your own."],["DANCE","Dance in the kitchen. It counts."],["SUNNY","A sunny thought can brighten a grey day."],["BALLOON","Let a worry float away like a balloon."],["TWIRL","Twirl just for the fun of it."],["CONFETTI","Celebrate small wins. Imaginary confetti is allowed."],["BUBBLES","Blowing bubbles is a lovely way to breathe out slowly."],["LAUGH","Laugh out loud at something small today."],["SMILE","A smile can light up a whole room."],["SING","Sing, even if it's just to yourself."],["PLAY","Play isn't only for children."],["CHEER","Cheer someone on today."]]},{"name":"Laughter","words":[["GIGGLE","Giggles are contagious in the best way."],["CHUCKLE","Let yourself chuckle at the little absurd things."],["SILLY","Being silly is good for grown-ups too."],["JOKE","Tell someone your favourite joke today."],["GRIN","Grin at yourself in the mirror. It might make you laugh."],["TICKLE","Let something tickle your funny bone."],["PUNS","Puns are the gentlest kind of mischief."],["WHIMSY","A little whimsy makes an ordinary day more fun."],["FUNNY","Find one funny thing today."],["CLOWN","Everyone can be a little bit of a clown."],["SMILE","Smiles are catching. Pass one on."],["GLEE","Glee: the happiest kind of laugh."],["HAPPY","Happiness often starts with a laugh."]]},{"name":"Rest","words":[["NAP","A short nap is a perfectly good plan."],["PAUSE","Pausing is part of the journey, not a detour."],["RECLINE","Lean back and let your body be held."],["LOUNGE","Lounge about for a bit. There’s no hurry."],["HAMMOCK","Let yourself sway for a while, real or imagined."],["IDLE","Idle time is how minds rest and wander."],["BREATHER","Take a breather. You deserve one."],["UNPLUG","Unplug for ten minutes and notice how it feels."],["SLEEP","Sleep is when your body mends itself."],["SOFA","Sink into the sofa. You've earned it."],["QUIET","A quiet moment is a small holiday."],["BREATHE","Breathe out slowly and let your shoulders drop."],["CALM","Calm is always there, underneath."]]},{"name":"Sleep","words":[["PILLOW","Rest your head and let the day go."],["DOZE","Doze a little. It’s fine to drift."],["DREAMY","Let your thoughts go soft and dreamy."],["SNOOZE","A gentle snooze can be a lovely treat."],["BEDTIME","A calm bedtime routine is a kindness to tomorrow’s you."],["PYJAMAS","Changing into pyjamas tells your day it’s done."],["YAWN","A big yawn is your body saying, “Time to rest.”"],["SLUMBER","Sink into slumber. Tomorrow can wait."],["DREAM","Sweet dreams are waiting."],["BLANKET","Tuck yourself in. Tomorrow can wait."],["MOON","The moon keeps watch while you sleep."],["LULLABY","Everyone deserves a lullaby."],["NIGHT","Night is the world's way of resting."]]},{"name":"Travel","words":[["JOURNEY","Enjoy the journey, not just the destination."],["SUITCASE","Pack light. Leave a worry behind."],["POSTCARD","Send someone a postcard. It’s a lovely surprise."],["TRAIN","Watch the world go by from a train window."],["MAP","There’s more than one route to where you’re going."],["WANDER","Wander without a plan for a little while."],["EXPLORE","Explore somewhere new, even a nearby street."],["SCENIC","Take the scenic route when you can."],["TICKET","A ticket to somewhere new."],["PLANE","From up high, worries look very small."],["ADVENTURE","Every trip is a small adventure."],["COMPASS","You'll always find your way back."],["BOAT","Let the boat rock you gently."]]},{"name":"Picnic","words":[["BASKET","Fill your basket with the things you love."],["RUG","Spread out a rug and make yourself at home outdoors."],["SANDWICH","A sandwich tastes better in the open air."],["BERRIES","Sweet berries are summer in a bite."],["FLASK","A flask of something warm makes any outing cosy."],["SHADE","Find some shade and let yourself relax."],["PARK","A stroll in the park can refresh a whole afternoon."],["GRAPES","Share your grapes. Picnics are for sharing."],["BLANKET","Spread the blanket and stay a while."],["LEMONADE","Cool lemonade on a warm day."],["APPLE","A crisp apple tastes better outdoors."],["CAKE","Bring cake. Picnics are for treats."],["SUNSHINE","Sunshine makes every sandwich taste better."]]},{"name":"Little Wins","words":[["TIDIED","Tidied one small corner? That’s a win."],["REPLIED","Replied to a message you’d been putting off? Well done."],["TRIED","You tried, and that matters."],["FINISHED","Finished something? Take a moment to feel good about it."],["STARTED","Starting is often the hardest part. You did it."],["PROGRESS","Progress is progress, however small."],["STEP","One step is still a step forward."],["DONE","Done is lovely. It doesn’t have to be perfect."],["RESTED","You rested. That's a win too."],["WATERED","You watered the plants, and yourself."],["LEARNED","You learned something new today."]]},{"name":"Words of Comfort","words":[["SAFE","You are safe in this moment."],["OKAY","It’s okay to not have it all figured out."],["HERE","I’m here. You’re here. That’s enough for now."],["SOOTHE","Soothe yourself the way you’d soothe a friend."],["HELD","You are held by more people than you know."],["ALRIGHT","It’ll be alright, one breath at a time."],["WELCOME","You are always welcome here."],["SHELTER","Find shelter in something that feels safe and kind."],["CALM","Calm is on its way."],["GENTLE","Be gentle with yourself right now."],["HUG","Here's a hug, in word form."],["REST","It's okay to rest."],["HOPE","There is always hope."]]}];
